/**
 * Render-phase conformance: process() output must match the reference
 * implementation byte-for-byte.
 *
 * Expected HTML generated by tools/transform-oracle.php --render
 * (typography and hyphenation disabled on the reference side - they are
 * covered by render-typo/render-full with other fixtures; emoticons off,
 * the reference default). The fixture emoticon-on.html is the same source
 * generated with --emoticon, to flag the non-default setting.
 */

import { Syntax } from "../src/Syntax.js";
import { renderConformance } from "./helpers/render-conformance.js";

renderConformance({
  suite: "conformance: rendered HTML matches the reference implementation",
  fixturesDir: "render",
  extension: ".html",
  convert: (texy, source) => texy.process(source),
  configure: (texy, name) => {
    texy.allowed[Syntax.Typography] = false; // fixtures generated with typography disabled
    texy.allowed[Syntax.Hyphenation] = false;
    // only the emoticon-on fixture was generated with --emoticon; the
    // plain fixtures (emoticon, showcase, ...) have emoticons off
    if (name === "emoticon-on") {
      texy.allowed[Syntax.Emoticon] = true;
    }
  },
});
